import { buildSchema, extendSchema } from 'graphql';
import { describe, expect, it } from 'vitest';

import { createSuperpositionApiExtension, getApiFieldName } from './api-extensions';
import { SuperpositionEntityFields } from './types';

const baseSchema = buildSchema(`
    scalar DateTime
    scalar JSON

    type Product {
        id: ID!
    }

    type ProductVariant {
        id: ID!
        price: Int!
    }

    type Query {
        product: Product
    }
`);

describe('Superposition API extensions', () => {
    it('exposes configured fields directly on their entities', () => {
        const extension = createSuperpositionApiExtension(
            baseSchema,
            entities({
                Product: [{ name: 'price', type: 'int' }],
                ProductVariant: [{ name: 'availableOn', type: 'datetime' }],
            }),
            false,
        );

        const schema = extendSchema(baseSchema, extension!);
        expect(schema.getType('Product')?.toString()).toBe('Product');
        expect((schema.getType('Product') as any).getFields().resolvedPrice.type.toString()).toBe('Int');
        expect(
            (schema.getType('ProductVariant') as any).getFields().resolvedAvailableOn.type.toString(),
        ).toBe('DateTime');
    });

    it('adds an Admin API helper query for Dashboard display', () => {
        const extension = createSuperpositionApiExtension(
            baseSchema,
            entities({
                ProductVariant: [{ name: 'bulkPrice', type: 'int' }],
            }),
            false,
        );

        const schema = extendSchema(baseSchema, extension!);
        const queryFields = (schema.getType('Query') as any).getFields();
        expect(queryFields.superpositionResolvedCustomFields.type.toString()).toBe(
            '[SuperpositionResolvedCustomField!]!',
        );
    });

    it('omits private fields from the Shop API extension', () => {
        const extension = createSuperpositionApiExtension(
            baseSchema,
            entities({
                Product: [
                    { name: 'publicValue', type: 'string' },
                    { name: 'privateValue', type: 'string', public: false },
                ],
            }),
            true,
        );

        const schema = extendSchema(baseSchema, extension!);
        const fields = (schema.getType('Product') as any).getFields();
        expect(fields.resolvedPublicValue).toBeDefined();
        expect(fields.resolvedPrivateValue).toBeUndefined();
        expect((schema.getType('Query') as any).getFields().superpositionResolvedCustomFields).toBeUndefined();
    });

    it('supports an explicit API field name and rejects collisions', () => {
        expect(getApiFieldName({ name: 'price', type: 'int', apiFieldName: 'contextualPrice' })).toBe(
            'contextualPrice',
        );
        expect(() =>
            createSuperpositionApiExtension(
                baseSchema,
                entities({
                    ProductVariant: [{ name: 'storedPrice', type: 'int', apiFieldName: 'price' }],
                }),
                false,
            ),
        ).toThrow('ProductVariant.price');
    });
});

function entities(
    input: Partial<SuperpositionEntityFields>,
): SuperpositionEntityFields {
    return {
        Product: input.Product ?? [],
        ProductVariant: input.ProductVariant ?? [],
    };
}

import { DocumentNode, GraphQLSchema, isObjectType, parse } from 'graphql';

import {
    SuperpositionCustomFieldConfig,
    SuperpositionEntityFields,
    SuperpositionSupportedEntityName,
} from './types';

export function createSuperpositionApiExtension(
    schema: GraphQLSchema | undefined,
    entities: SuperpositionEntityFields,
    publicOnly: boolean,
): DocumentNode | undefined {
    const hasAdminFields = Object.values(entities).some(fields =>
        fields.some(field => field.internal !== true),
    );
    const extensions = (Object.entries(entities) as Array<
        [SuperpositionSupportedEntityName, SuperpositionCustomFieldConfig[]]
    >)
        .map(([entityName, fields]) => {
            const exposedFields = fields.filter(
                field => field.internal !== true && (!publicOnly || field.public !== false),
            );
            if (exposedFields.length === 0) {
                return;
            }

            assertFieldsCanBeExtended(schema, entityName, exposedFields);
            return `
                extend type ${entityName} {
                    ${exposedFields
                        .map(field => `${getApiFieldName(field)}: ${getGraphQlType(entityName, field)}`)
                        .join('\n')}
                }
            `;
        })
        .filter((extension): extension is string => extension != null);

    if (!publicOnly && hasAdminFields) {
        extensions.push(`
            type SuperpositionResolvedCustomField {
                entityName: String!
                entityId: ID!
                fieldName: String!
                apiFieldName: String!
                storedValue: JSON
                resolvedValue: JSON
            }

            extend type Query {
                superpositionResolvedCustomFields(entityName: String!, entityId: ID!): [SuperpositionResolvedCustomField!]!
            }
        `);
    }

    return extensions.length > 0 ? parse(extensions.join('\n')) : undefined;
}

export function getApiFieldName(field: SuperpositionCustomFieldConfig): string {
    return field.apiFieldName ?? `resolved${pascalCase(field.name)}`;
}

function assertFieldsCanBeExtended(
    schema: GraphQLSchema | undefined,
    entityName: SuperpositionSupportedEntityName,
    fields: SuperpositionCustomFieldConfig[],
) {
    const fieldNames = new Set<string>();
    const entityType = schema?.getType(entityName);

    for (const field of fields) {
        const fieldName = getApiFieldName(field);
        if (fieldNames.has(fieldName)) {
            throw new Error(`Superposition config exposes "${entityName}.${fieldName}" more than once.`);
        }
        fieldNames.add(fieldName);

        if (isObjectType(entityType) && entityType.getFields()[fieldName]) {
            throw new Error(
                `Superposition cannot expose "${entityName}.${fieldName}" because that GraphQL field already exists. Set "apiFieldName" to a different name.`,
            );
        }
    }
}

function getGraphQlType(
    entityName: SuperpositionSupportedEntityName,
    field: SuperpositionCustomFieldConfig,
): string {
    let type: string;
    switch (field.type) {
        case 'string':
        case 'localeString':
        case 'text':
        case 'localeText':
            type = 'String';
            break;
        case 'int':
            type = 'Int';
            break;
        case 'float':
            type = 'Float';
            break;
        case 'boolean':
            type = 'Boolean';
            break;
        case 'datetime':
            type = 'DateTime';
            break;
        case 'struct':
            type = `${entityName}${pascalCase(field.name)}Struct`;
            break;
        default:
            throw new Error(
                `Superposition does not support the "${(field as { type: string }).type}" custom field type.`,
            );
    }
    return field.list === true ? `[${type}!]` : type;
}

function pascalCase(input: string): string {
    return input.charAt(0).toUpperCase() + input.slice(1);
}

import { RequestContext } from '@vendure/core';
import { describe, expect, it, vi } from 'vitest';

import { SuperpositionRuntimeService } from './superposition-runtime.service';

describe('SuperpositionRuntimeService', () => {
    it('resolves a field with Vendure request and entity dimensions', async () => {
        const resolveAllConfigDetails = vi.fn().mockResolvedValue({ bulkPrice: '1200' });
        const service = new SuperpositionRuntimeService({
            provider: {
                endpoint: 'http://localhost:8081',
                token: 'token',
                org_id: 'localorg',
                workspace_id: 'vendure',
            },
        });
        Object.assign(service as any, {
            initPromise: Promise.resolve(),
            provider: { resolveAllConfigDetails },
        });

        const result = await service.resolveEntityFieldValue(
            {
                channel: { code: 'b2b', defaultCurrencyCode: 'INR' },
                currencyCode: 'USD',
            } as RequestContext,
            'ProductVariant',
            { id: '42' },
            { name: 'bulkPrice', type: 'int' },
            800,
        );

        expect(result).toBe(1200);
        expect(resolveAllConfigDetails).toHaveBeenCalledWith(
            { bulkPrice: 800 },
            {
                channel: 'b2b',
                currency: 'USD',
                entity: 'product_variant',
                entity_id: 42,
                targetingKey: '42',
            },
        );
    });

    it('returns the persisted value when provider resolution fails', async () => {
        const service = new SuperpositionRuntimeService({});
        Object.assign(service as any, {
            initPromise: Promise.resolve(),
            provider: {
                resolveAllConfigDetails: vi.fn().mockRejectedValue(new Error('provider unavailable')),
            },
        });

        const result = await service.resolveEntityFieldValue(
            {
                channel: { code: 'default', defaultCurrencyCode: 'INR' },
                currencyCode: 'INR',
            } as RequestContext,
            'Product',
            { id: 1 },
            { name: 'price', type: 'int' },
            1000,
        );

        expect(result).toBe(1000);
    });
});

import { Type } from '@nestjs/common';
import { Parent, ResolveField, Resolver } from '@nestjs/graphql';
import { Permission } from '@vendure/common/lib/generated-types';
import { Ctx, Product, ProductVariant, RequestContext } from '@vendure/core';

import { getApiFieldName } from './api-extensions';
import { SuperpositionRuntimeService } from './superposition-runtime.service';
import {
    SuperpositionCustomFieldConfig,
    SuperpositionEntityFields,
    SuperpositionSupportedEntityName,
} from './types';

type SupportedEntity = Product | ProductVariant;

export function createSuperpositionResolvers(
    entities: SuperpositionEntityFields,
    publicOnly: boolean,
): Array<Type<any>> {
    return (Object.entries(entities) as Array<
        [SuperpositionSupportedEntityName, SuperpositionCustomFieldConfig[]]
    >).flatMap(([entityName, fields]) =>
        fields
            .filter(field => field.internal !== true && (!publicOnly || field.public !== false))
            .map(field => createEntityFieldResolver(entityName, field)),
    );
}

function createEntityFieldResolver(
    entityName: SuperpositionSupportedEntityName,
    field: SuperpositionCustomFieldConfig,
): Type<any> {
    const apiFieldName = getApiFieldName(field);

    @Resolver(entityName)
    class SuperpositionEntityFieldResolver {
        constructor(private readonly runtimeService: SuperpositionRuntimeService) {}

        @ResolveField(apiFieldName)
        resolve(@Ctx() ctx: RequestContext, @Parent() entity: SupportedEntity) {
            if (!userCanReadField(ctx, field)) {
                return null;
            }
            const customFields = entity.customFields as Record<string, unknown> | undefined;
            return this.runtimeService.resolveEntityFieldValue(
                ctx,
                entityName,
                entity,
                field,
                customFields?.[field.name],
            );
        }
    }

    Object.defineProperty(SuperpositionEntityFieldResolver, 'name', {
        value: `Superposition${entityName}${pascalCase(apiFieldName)}Resolver`,
    });
    return SuperpositionEntityFieldResolver;
}

function userCanReadField(ctx: RequestContext, field: SuperpositionCustomFieldConfig): boolean {
    if (ctx.apiType === 'shop' && field.public === true) {
        return true;
    }
    const required = field.requiresPermission;
    if (required == null) {
        return true;
    }
    const permissions = (Array.isArray(required) ? required : [required]) as Permission[];
    return permissions.length === 0 || ctx.userHasPermissions(permissions);
}

function pascalCase(input: string): string {
    return input.charAt(0).toUpperCase() + input.slice(1);
}

import { CustomFieldConfig, RelationCustomFieldConfig } from '@vendure/core';
import type { SuperpositionProviderOptions as ProviderOptions } from 'superposition-provider';

export type SuperpositionProviderOptions = ProviderOptions;

export type SuperpositionSupportedEntityName = 'Product' | 'ProductVariant';

export type SuperpositionCustomFieldConfig = Exclude<
    CustomFieldConfig,
    RelationCustomFieldConfig
> & {
    /**
     * The field exposed directly on the GraphQL entity.
     * Defaults to `resolved${PascalCase(customFieldName)}`.
     */
    apiFieldName?: string;
};

export type SuperpositionEntityFields = Record<
    SuperpositionSupportedEntityName,
    SuperpositionCustomFieldConfig[]
>;

export type SuperpositionPluginOptions = {
    entities?: Partial<Record<SuperpositionSupportedEntityName, SuperpositionCustomFieldConfig[]>>;
    openFeatureDomain?: string;
    provider?: Partial<SuperpositionProviderOptions>;
    providerInitializationRetryIntervalMs?: number;
};

export const SUPERPOSITION_OPTIONS = Symbol('SUPERPOSITION_OPTIONS');

import { Inject } from '@nestjs/common';
import { Args, Query, Resolver } from '@nestjs/graphql';
import {
    Allow,
    Ctx,
    EntityNotFoundError,
    Permission,
    Product,
    ProductVariant,
    RequestContext,
    TransactionalConnection,
} from '@vendure/core';

import { getApiFieldName } from './api-extensions';
import { SuperpositionRuntimeService } from './superposition-runtime.service';
import {
    SUPERPOSITION_OPTIONS,
    SuperpositionCustomFieldConfig,
    SuperpositionEntityFields,
    SuperpositionPluginOptions,
    SuperpositionSupportedEntityName,
} from './types';

type QueryArgs = {
    entityName: string;
    entityId: string | number;
};

type SupportedEntity = Product | ProductVariant;

@Resolver()
export class SuperpositionAdminResolver {
    constructor(
        private readonly connection: TransactionalConnection,
        private readonly runtimeService: SuperpositionRuntimeService,
        @Inject(SUPERPOSITION_OPTIONS)
        private readonly options: SuperpositionPluginOptions,
    ) {}

    @Query()
    @Allow(Permission.ReadCatalog)
    async superpositionResolvedCustomFields(@Ctx() ctx: RequestContext, @Args() args: QueryArgs) {
        const entityName = this.getSupportedEntityName(args.entityName);
        const entity = await this.getEntity(ctx, entityName, args.entityId);
        const customFields = entity.customFields as Record<string, unknown> | undefined;
        const fields = this.getEntities()[entityName];

        return Promise.all(
            fields
                .filter(field => field.internal !== true && this.userCanReadField(ctx, field))
                .map(async field => {
                    const storedValue = customFields?.[field.name] ?? null;
                    const resolvedValue = await this.runtimeService.resolveEntityFieldValue(
                        ctx,
                        entityName,
                        entity,
                        field,
                        storedValue,
                    );

                    return {
                        entityName,
                        entityId: String(entity.id),
                        fieldName: field.name,
                        apiFieldName: getApiFieldName(field),
                        storedValue,
                        resolvedValue,
                    };
                }),
        );
    }

    private async getEntity(
        ctx: RequestContext,
        entityName: SuperpositionSupportedEntityName,
        entityId: string | number,
    ): Promise<SupportedEntity> {
        const entityType = entityName === 'Product' ? Product : ProductVariant;
        const entity = await this.connection.getRepository(ctx, entityType).findOne({
            where: { id: entityId as any },
        });
        if (!entity) {
            throw new EntityNotFoundError(entityName, String(entityId));
        }
        return entity;
    }

    private getEntities(): SuperpositionEntityFields {
        return {
            Product: this.options.entities?.Product ?? [],
            ProductVariant: this.options.entities?.ProductVariant ?? [],
        };
    }

    private getSupportedEntityName(entityName: string): SuperpositionSupportedEntityName {
        if (entityName === 'Product' || entityName === 'ProductVariant') {
            return entityName;
        }
        throw new Error(`Superposition does not support entity "${entityName}".`);
    }

    private userCanReadField(ctx: RequestContext, field: SuperpositionCustomFieldConfig): boolean {
        const required = field.requiresPermission;
        if (required == null) {
            return true;
        }
        const permissions = (Array.isArray(required) ? required : [required]) as Permission[];
        return permissions.length === 0 || ctx.userHasPermissions(permissions);
    }
}

import {
    CustomFieldConfig,
    PluginCommonModule,
    RuntimeVendureConfig,
    VendurePlugin,
} from '@vendure/core';

import { createSuperpositionApiExtension } from './api-extensions';
import { SuperpositionAdminResolver } from './superposition-admin.resolver';
import { createSuperpositionResolvers } from './superposition.resolver';
import { SuperpositionRuntimeService } from './superposition-runtime.service';
import {
    SUPERPOSITION_OPTIONS,
    SuperpositionCustomFieldConfig,
    SuperpositionEntityFields,
    SuperpositionPluginOptions,
    SuperpositionSupportedEntityName,
} from './types';

@VendurePlugin({
    imports: [PluginCommonModule],
    compatibility: '^3.6.0',
    dashboard: './dashboard/index.tsx',
    adminApiExtensions: {
        schema: schema =>
            createSuperpositionApiExtension(schema, SuperpositionPlugin.getEntities(), false),
        resolvers: () => [
            SuperpositionAdminResolver,
            ...createSuperpositionResolvers(SuperpositionPlugin.getEntities(), false),
        ],
    },
    shopApiExtensions: {
        schema: schema =>
            createSuperpositionApiExtension(schema, SuperpositionPlugin.getEntities(), true),
        resolvers: () => createSuperpositionResolvers(SuperpositionPlugin.getEntities(), true),
    },
    providers: [
        SuperpositionRuntimeService,
        {
            provide: SUPERPOSITION_OPTIONS,
            useFactory: () => SuperpositionPlugin.options,
        },
    ],
    configuration: config => SuperpositionPlugin.configureCustomFields(config),
})
export class SuperpositionPlugin {
    static options: SuperpositionPluginOptions = {};

    static init(options: SuperpositionPluginOptions = {}) {
        this.options = options;
        return SuperpositionPlugin;
    }

    static getEntities(): SuperpositionEntityFields {
        return {
            Product: this.options.entities?.Product ?? [],
            ProductVariant: this.options.entities?.ProductVariant ?? [],
        };
    }

    private static getEntityEntries(): Array<
        [SuperpositionSupportedEntityName, SuperpositionCustomFieldConfig[]]
    > {
        const entities = this.getEntities();
        return [
            ['Product', entities.Product],
            ['ProductVariant', entities.ProductVariant],
        ];
    }

    private static configureCustomFields(config: RuntimeVendureConfig): RuntimeVendureConfig {
        for (const [entityName, fields] of this.getEntityEntries()) {
            config.customFields[entityName] ??= [];

            for (const field of fields) {
                const { apiFieldName: _apiFieldName, ...customField } = field;
                const existingField = config.customFields[entityName]?.find(
                    configuredField => configuredField.name === field.name,
                );
                if (existingField) {
                    this.assertCompatibleField(entityName, existingField, field);
                } else {
                    config.customFields[entityName]?.push(customField as CustomFieldConfig);
                }
            }
        }
        return config;
    }

    private static assertCompatibleField(
        entityName: SuperpositionSupportedEntityName,
        existingField: CustomFieldConfig,
        configuredField: SuperpositionCustomFieldConfig,
    ) {
        if (
            existingField.type !== configuredField.type ||
            (existingField.list === true) !== (configuredField.list === true)
        ) {
            throw new Error(
                `Superposition field "${entityName}.${configuredField.name}" does not match the existing custom field type or list setting.`,
            );
        }
    }
}

import { Inject, Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import {
    AsyncLocalStorageTransactionContextPropagator,
    OpenFeature,
    type EvaluationContext,
    type Provider,
} from '@openfeature/server-sdk';
import { CustomFieldConfig, RequestContext } from '@vendure/core';

import {
    SUPERPOSITION_OPTIONS,
    SuperpositionPluginOptions,
    SuperpositionProviderOptions,
    SuperpositionSupportedEntityName,
} from './types';

type SuperpositionProvider = Provider & {
    resolveAllConfigDetails(
        defaultValue: Record<string, unknown>,
        context: EvaluationContext,
    ): Promise<Record<string, unknown>>;
};

type EntityWithId = {
    id: unknown;
};

type RuntimeDimensions = {
    channel?: string;
    currency?: string;
    entity?: 'product' | 'product_variant';
    entity_id?: string | number;
};

@Injectable()
export class SuperpositionRuntimeService implements OnModuleDestroy {
    private static transactionContextConfigured = false;
    private readonly logger = new Logger(SuperpositionRuntimeService.name);
    private initPromise: Promise<void> | undefined;
    private provider: SuperpositionProvider | undefined;
    private retryProviderAfter = 0;

    constructor(
        @Inject(SUPERPOSITION_OPTIONS)
        private options: SuperpositionPluginOptions,
    ) {
        if (!SuperpositionRuntimeService.transactionContextConfigured) {
            OpenFeature.setTransactionContextPropagator(
                new AsyncLocalStorageTransactionContextPropagator(),
            );
            SuperpositionRuntimeService.transactionContextConfigured = true;
        }
    }

    async resolveEntityFieldValue(
        ctx: RequestContext,
        entityName: SuperpositionSupportedEntityName,
        entity: EntityWithId,
        field: CustomFieldConfig,
        defaultValue: unknown,
    ): Promise<unknown> {
        const key = field.name;
        const fallbackValue = defaultValue ?? null;
        const evaluationContext = this.toEvaluationContext(
            this.getRequestDimensions(ctx, entityName, entity),
        );

        try {
            await this.ensureProvider();

            const provider = this.provider;
            if (!provider) {
                return fallbackValue;
            }

            const defaults = this.createDefaultConfig(key, fallbackValue);
            const resolvedConfig = await this.withEvaluationContext(evaluationContext, () =>
                provider.resolveAllConfigDetails(defaults, evaluationContext),
            );
            const rawValue = this.getNestedValue(resolvedConfig, key);
            return this.coerceFieldValue(field, rawValue, fallbackValue);
        } catch (error) {
            if (this.provider) {
                const message = error instanceof Error ? error.message : String(error);
                this.logger.warn(
                    `Failed to resolve Superposition value for "${key}", using fallback: ${message}`,
                );
            }
            return fallbackValue;
        }
    }

    async onModuleDestroy(): Promise<void> {
        if (this.provider?.onClose) {
            await this.provider.onClose();
        }
    }

    private getRequestDimensions(
        ctx: RequestContext,
        entityName: SuperpositionSupportedEntityName,
        entity: EntityWithId,
    ): RuntimeDimensions {
        return {
            channel: ctx.channel?.code,
            currency: ctx.currencyCode ?? ctx.channel?.defaultCurrencyCode,
            entity: entityName === 'Product' ? 'product' : 'product_variant',
            entity_id: this.normalizeEntityId(entity.id),
        };
    }

    private normalizeEntityId(id: unknown): string | number {
        if (typeof id === 'number') {
            return id;
        }
        if (typeof id === 'string' && /^\d+$/.test(id)) {
            return Number(id);
        }
        return String(id);
    }

    private async ensureProvider(): Promise<void> {
        if (Date.now() < this.retryProviderAfter) {
            return;
        }
        if (this.initPromise) {
            return this.initPromise;
        }

        this.initPromise = (async () => {
            const config = this.getProviderConfig();
            const { SuperpositionProvider } = await this.loadProviderModule();
            const provider = new SuperpositionProvider(config);
            try {
                // Register the provider with OpenFeature for lifecycle/transaction-context support,
                // while using Superposition's extended resolveAllConfigDetails API directly.
                await OpenFeature.setProviderAndWait(this.getOpenFeatureDomain(), provider);
                this.provider = provider;
                this.retryProviderAfter = 0;
                this.logger.log(
                    `Superposition OpenFeature provider initialized against ${config.endpoint} (${config.org_id}/${config.workspace_id})`,
                );
            } catch (error) {
                await provider.onClose?.();
                throw error;
            }
        })().catch(error => {
            this.provider = undefined;
            this.initPromise = undefined;
            this.retryProviderAfter =
                Date.now() + (this.options.providerInitializationRetryIntervalMs ?? 5000);
            const message = error instanceof Error ? error.message : String(error);
            this.logger.error(`Failed to initialize Superposition provider: ${message}`);
            throw error;
        });

        return this.initPromise;
    }

    private getProviderConfig(): SuperpositionProviderOptions {
        return {
            ...this.options.provider,
            endpoint:
                this.options.provider?.endpoint ??
                process.env.SUPERPOSITION_ENDPOINT ??
                'http://localhost:8080',
            token: this.options.provider?.token ?? process.env.SUPERPOSITION_TOKEN ?? 'local-dev-token',
            org_id: this.options.provider?.org_id ?? process.env.SUPERPOSITION_ORG_ID ?? 'localorg',
            workspace_id:
                this.options.provider?.workspace_id ?? process.env.SUPERPOSITION_WORKSPACE_ID ?? 'dev',
            refreshStrategy: this.options.provider?.refreshStrategy ?? {
                interval: Number(process.env.SUPERPOSITION_POLL_INTERVAL_MS ?? 1000),
            },
        };
    }

    private async loadProviderModule(): Promise<{
        SuperpositionProvider: new (config: SuperpositionProviderOptions) => SuperpositionProvider;
    }> {
        return import('superposition-provider');
    }

    private getOpenFeatureDomain(): string {
        return this.options.openFeatureDomain ?? 'superposition';
    }

    private toEvaluationContext(dimensions: RuntimeDimensions): EvaluationContext {
        return {
            ...dimensions,
            targetingKey: String(dimensions.entity_id ?? 'vendure'),
        };
    }

    private withEvaluationContext<T>(context: EvaluationContext, callback: () => Promise<T>): Promise<T> {
        return new Promise<T>((resolve, reject) => {
            OpenFeature.setTransactionContext(context, () => {
                callback().then(resolve, reject);
            });
        });
    }

    private createDefaultConfig(key: string, value: unknown): Record<string, unknown> {
        return { [key]: value };
    }

    private getNestedValue(input: unknown, key: string): unknown {
        if (input == null || typeof input !== 'object') {
            return undefined;
        }
        return (input as Record<string, unknown>)[key];
    }

    private coerceFieldValue(
        field: CustomFieldConfig,
        value: unknown,
        fallbackValue: unknown,
    ): unknown {
        if (value === undefined) {
            return fallbackValue;
        }
        if (field.list === true) {
            if (value === null) {
                return fallbackValue;
            }
            const values = Array.isArray(value) ? value : [value];
            return values.map(item => this.coerceScalarFieldValue(field, item, null));
        }
        return this.coerceScalarFieldValue(field, value, fallbackValue);
    }

    private coerceScalarFieldValue(
        field: CustomFieldConfig,
        value: unknown,
        fallbackValue: unknown,
    ): unknown {
        if (value === null) {
            return null;
        }

        switch (field.type) {
            case 'int': {
                const parsed = typeof value === 'number' ? value : parseInt(String(value), 10);
                return Number.isFinite(parsed) ? Math.trunc(parsed) : fallbackValue;
            }
            case 'float': {
                const parsed = typeof value === 'number' ? value : parseFloat(String(value));
                return Number.isFinite(parsed) ? parsed : fallbackValue;
            }
            case 'boolean':
                if (typeof value === 'boolean') {
                    return value;
                }
                if (typeof value === 'string') {
                    const lower = value.trim().toLowerCase();
                    if (lower === 'true') {
                        return true;
                    }
                    if (lower === 'false') {
                        return false;
                    }
                }
                if (typeof value === 'number') {
                    return value !== 0;
                }
                return fallbackValue;
            case 'datetime': {
                const date = value instanceof Date ? value : new Date(String(value));
                return Number.isNaN(date.getTime()) ? fallbackValue : date;
            }
            case 'string':
            case 'localeString':
            case 'text':
            case 'localeText':
                if (typeof value === 'string') {
                    return value;
                }
                if (typeof value === 'number' || typeof value === 'boolean') {
                    return String(value);
                }
                return fallbackValue;
            case 'struct':
                return value;
            case 'relation':
                return fallbackValue;
            default:
                return value;
        }
    }
}

import {
    Badge,
    defineDashboardExtension,
    Skeleton,
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
    api,
} from '@vendure/dashboard';
import { useQuery } from '@tanstack/react-query';
import { parse } from 'graphql';

type ResolvedField = {
    entityName: string;
    entityId: string;
    fieldName: string;
    apiFieldName: string;
    storedValue: unknown;
    resolvedValue: unknown;
};

const resolvedFieldsDocument = parse(`
    query SuperpositionResolvedCustomFields($entityName: String!, $entityId: ID!) {
        superpositionResolvedCustomFields(entityName: $entityName, entityId: $entityId) {
            entityName
            entityId
            fieldName
            apiFieldName
            storedValue
            resolvedValue
        }
    }
`);

function ResolvedValuesBlock({
    entityName,
    entityId,
}: Readonly<{
    entityName: 'Product' | 'ProductVariant';
    entityId?: string;
}>) {
    const { data, isLoading, error } = useQuery({
        queryKey: ['superpositionResolvedCustomFields', entityName, entityId],
        enabled: entityId != null,
        queryFn: async () =>
            api.query<{
                superpositionResolvedCustomFields: ResolvedField[];
            }>(resolvedFieldsDocument, {
                entityName,
                entityId: entityId as string,
            }),
    });

    if (entityId == null) {
        return null;
    }

    if (isLoading) {
        return (
            <div className="space-y-3">
                <Skeleton className="h-5 w-36" />
                <Skeleton className="h-20 w-full" />
            </div>
        );
    }

    if (error) {
        return <p className="text-sm text-muted-foreground">Unable to load Superposition values.</p>;
    }

    const fields = data?.superpositionResolvedCustomFields ?? [];
    if (fields.length === 0) {
        return <p className="text-sm text-muted-foreground">No Superposition fields configured.</p>;
    }

    return (
        <Table>
            <TableHeader>
                <TableRow>
                    <TableHead>Field</TableHead>
                    <TableHead>Stored</TableHead>
                    <TableHead>Resolved</TableHead>
                    <TableHead>API field</TableHead>
                </TableRow>
            </TableHeader>
            <TableBody>
                {fields.map(field => {
                    const isOverridden = formatValue(field.storedValue) !== formatValue(field.resolvedValue);
                    return (
                        <TableRow key={field.fieldName}>
                            <TableCell className="font-medium">{field.fieldName}</TableCell>
                            <TableCell>{formatValue(field.storedValue)}</TableCell>
                            <TableCell>
                                <span className="inline-flex items-center gap-2">
                                    {formatValue(field.resolvedValue)}
                                    {isOverridden && <Badge variant="secondary">Override</Badge>}
                                </span>
                            </TableCell>
                            <TableCell className="text-muted-foreground">{field.apiFieldName}</TableCell>
                        </TableRow>
                    );
                })}
            </TableBody>
        </Table>
    );
}

function formatValue(value: unknown): string {
    if (value == null) {
        return '-';
    }
    if (typeof value === 'object') {
        return JSON.stringify(value);
    }
    return String(value);
}

defineDashboardExtension({
    pageBlocks: [
        {
            id: 'superposition-product-values',
            title: 'Superposition values',
            location: {
                pageId: 'product-detail',
                column: 'side',
                position: { blockId: 'enabled-toggle', order: 'after' },
            },
            component: ({ context }) => (
                <ResolvedValuesBlock entityName="Product" entityId={context.entity?.id} />
            ),
        },
        {
            id: 'superposition-product-variant-values',
            title: 'Superposition values',
            location: {
                pageId: 'product-variant-detail',
                column: 'side',
                position: { blockId: 'enabled', order: 'after' },
            },
            component: ({ context }) => (
                <ResolvedValuesBlock entityName="ProductVariant" entityId={context.entity?.id} />
            ),
        },
    ],
});
